class Solution {
public:
    int findContentChildren(vector<int>& g, vector<int>& s) {
        sort(g.begin(), g.end());
        sort(s.begin(), s.end());
        int kid = 0;
        for (int c = 0; c < (int)s.size() && kid < (int)g.size(); c++) {
            if (s[c] >= g[kid]) kid++;
        }
        return kid;
    }
};
